1	import {
2	  BoxRenderable,
3	  type CliRenderer,
4	  type KeyEvent,
5	  ScrollBoxRenderable,
6	  TextRenderable,
7	} from '@opentui/core';
8	import { getErrorMessage } from '../../core/errors.js';
9	import { ansiToStyledText, drawHalfCourt, formatTable } from '../../shared/utils/formatters.js';
10	import { Theme } from '../../shared/utils/theme.js';
11	import {
12	  type BoxScoreRow,
13	  type GameShotRow,
14	  loadBoxScoreWithTeamDedup,
15	  loadGameShots,
16	  loadRecentGames,
17	  type RecentGameRow,
18	} from './queries.js';
19	
20	export class GameCenterTab {
21	  readonly id = 'game-center';
22	  readonly name = 'Game Center';
23	  readonly container: BoxRenderable;
24	
25	  // UI Components
26	  private readonly leftPanel: BoxRenderable;
27	  private readonly middlePanel: BoxRenderable;
28	  private readonly rightPanel: BoxRenderable;
29	
30	  private readonly gameListScroll: ScrollBoxRenderable;
31	  private readonly gameListText: TextRenderable;
32	
33	  private readonly boxScoreScroll: ScrollBoxRenderable;
34	  private readonly boxScoreText: TextRenderable;
35	
36	  private readonly shotChartText: TextRenderable;
37	
38	  // State
39	  private games: RecentGameRow[] = [];
40	  private selectedGameIdx = 0;
41	
42	  private boxScores: BoxScoreRow[] = [];
43	  private selectedPlayerIdx = -1; // -1 means "All Players"
44	
45	  private shots: GameShotRow[] = [];
46	
47	  // Focus Management: 0 = games, 1 = box score, 2 = shot chart
48	  private focusIndex = 0;
49	  private focusablePanels: BoxRenderable[] = [];
50	
51	  constructor(renderer: CliRenderer) {
52	    // Parent container spanning 100% of workspace width/height
53	    this.container = new BoxRenderable(renderer, {
54	      id: 'game-center-container',
55	      width: '100%',
56	      height: '100%',
57	      flexDirection: 'row',
58	      gap: Theme.gap,
59	      backgroundColor: Theme.background,
60	    });
61	
62	    // Left Panel: Game Directory
63	    this.leftPanel = new BoxRenderable(renderer, {
64	      id: 'game-directory-panel',
65	      width: '20%',
66	      height: '100%',
67	      border: true,
68	      borderStyle: Theme.borderStyle,
69	      borderColor: Theme.borderNormal,
70	      focusable: true,
71	      focusedBorderColor: Theme.borderFocused,
72	      title: 'Games',
73	      titleAlignment: Theme.titleAlignment,
74	    });
75	
76	    this.gameListScroll = new ScrollBoxRenderable(renderer, {
77	      id: 'game-list-scroll',
78	      width: '100%',
79	      height: '100%',
80	      viewportCulling: true,
81	    });
82	
83	    this.gameListText = new TextRenderable(renderer, {
84	      id: 'game-list-text',
85	      content: 'Loading games...',
86	      wrapMode: 'none',
87	    });
88	
89	    this.gameListScroll.add(this.gameListText);
90	    this.leftPanel.add(this.gameListScroll);
91	
92	    // Middle Panel: Box Score Details
93	    this.middlePanel = new BoxRenderable(renderer, {
94	      id: 'box-score-panel',
95	      width: '48%',
96	      height: '100%',
97	      border: true,
98	      borderStyle: Theme.borderStyle,
99	      borderColor: Theme.borderNormal,
100	      focusable: true,
101	      focusedBorderColor: Theme.borderFocused,
102	      title: 'Box Score',
103	      titleAlignment: Theme.titleAlignment,
104	    });
105	
106	    this.boxScoreScroll = new ScrollBoxRenderable(renderer, {
107	      id: 'box-score-scroll',
108	      width: '100%',
109	      height: '100%',
110	      viewportCulling: true,
111	    });
112	
113	    this.boxScoreText = new TextRenderable(renderer, {
114	      id: 'box-score-text',
115	      content: 'Select a game to view box scores.',
116	      wrapMode: 'none',
117	    });
118	
119	    this.boxScoreScroll.add(this.boxScoreText);
120	    this.middlePanel.add(this.boxScoreScroll);
121	
122	    // Right Panel: Shot Chart Visualisation
123	    this.rightPanel = new BoxRenderable(renderer, {
124	      id: 'shot-chart-panel',
125	      width: '32%',
126	      height: '100%',
127	      border: true,
128	      borderStyle: Theme.borderStyle,
129	      borderColor: Theme.borderNormal,
130	      focusable: true,
131	      focusedBorderColor: Theme.borderFocused,
132	      title: 'Shot Chart',
133	      titleAlignment: Theme.titleAlignment,
134	    });
135	
136	    this.shotChartText = new TextRenderable(renderer, {
137	      id: 'shot-chart-text',
138	      content: 'Select a game with shots to draw court.',
139	      wrapMode: 'none',
140	    });
141	
142	    this.rightPanel.add(this.shotChartText);
143	
144	    // Assembly
145	    this.container.add(this.leftPanel);
146	    this.container.add(this.middlePanel);
147	    this.container.add(this.rightPanel);
148	
149	    // Focus arrays
150	    this.focusablePanels = [this.leftPanel, this.middlePanel, this.rightPanel];
151	  }
152	
153	  /**
154	   * Initializes the tab by loading recent games from the database.
155	   */
156	  async init() {
157	    try {
158	      this.games = await loadRecentGames();
159	
160	      if (this.games.length > 0) {
161	        this.selectedGameIdx = 0;
162	        this.renderGameList();
163	        await this.loadGameDetails();
164	      } else {
165	        this.gameListText.content = ansiToStyledText('No games found in database.');
166	        this.container.requestRender();
167	      }
168	    } catch (e: unknown) {
169	      this.gameListText.content = ansiToStyledText(`Error loading games:\n${getErrorMessage(e)}`);
170	      this.container.requestRender();
171	    }
172	  }
173	
174	  /**
175	   * Switches focus to the current sub-panel and wires scroll focus.
176	   */
177	  focus() {
178	    this.focusActivePanel();
179	  }
180	
181	  /**
182	   * Cycles focus forward: games → box score → shot chart.
183	   */
184	  cycleFocus() {
185	    this.focusIndex = (this.focusIndex + 1) % this.focusablePanels.length;
186	    this.focus();
187	  }
188	
189	  /**
190	   * Cycles focus backward (reverse of cycleFocus).
191	   */
192	  cycleFocusBackward() {
193	    this.focusIndex =
194	      (this.focusIndex - 1 + this.focusablePanels.length) % this.focusablePanels.length;
195	    this.focus();
196	  }
197	
198	  /**
199	   * Footer status line for the app shell.
200	   */
201	  getStatusLine(): string {
202	    const gameCount = this.games.length;
203	    const gamePos = gameCount > 0 ? `${this.selectedGameIdx + 1}/${gameCount}` : '0/0';
204	    const panelLabels = ['Games', 'Box score', 'Shot chart'];
205	    const panel = panelLabels[this.focusIndex] ?? 'Games';
206	
207	    let playerLabel = 'All Players';
208	    if (this.selectedPlayerIdx >= 0 && this.boxScores[this.selectedPlayerIdx]) {
209	      playerLabel = this.boxScores[this.selectedPlayerIdx].full_name;
210	    }
211	
212	    const moveHint =
213	      this.focusIndex === 0
214	        ? '↑↓ move game'
215	        : this.focusIndex === 1
216	          ? '↑↓ move player'
217	          : 'read-only';
218	
219	    return `Games ${gamePos} | ${panel} | Player: ${playerLabel} | ${moveHint}`;
220	  }
221	
222	  private focusActivePanel() {
223	    this.focusablePanels.forEach((panel, idx) => {
224	      if (idx === this.focusIndex) {
225	        panel.focus();
226	      } else {
227	        panel.blur();
228	        panel.borderColor = Theme.borderNormal;
229	      }
230	    });
231	
232	    if (this.focusIndex === 0) {
233	      this.gameListScroll.focus();
234	    } else if (this.focusIndex === 1) {
235	      this.boxScoreScroll.focus();
236	    }
237	
238	    this.container.requestRender();
239	  }
240	
241	  isInputFocused(): boolean {
242	    return false;
243	  }
244	
245	  blurInput() {
246	    // Game Center doesn't have an input field to blur
247	  }
248	
249	  /**
250	   * Handles keyboard navigation within the Game Center tab.
251	   * Returns true if the key was handled, false otherwise.
252	   */
253	  handleKeyPress(event: KeyEvent): boolean {
254	    if (this.focusIndex === 0) {
255	      // Game Directory focused
256	      if (event.name === 'up') {
257	        if (this.selectedGameIdx > 0) {
258	          this.selectedGameIdx--;
259	          this.selectedPlayerIdx = -1; // Reset player filter on game change
260	          this.renderGameList();
261	          this.scrollGameListIntoView();
262	          this.loadGameDetails();
263	        }
264	        return true;
265	      }
266	      if (event.name === 'down') {
267	        if (this.selectedGameIdx < this.games.length - 1) {
268	          this.selectedGameIdx++;
269	          this.selectedPlayerIdx = -1; // Reset player filter on game change
270	          this.renderGameList();
271	          this.scrollGameListIntoView();
272	          this.loadGameDetails();
273	        }
274	        return true;
275	      }
276	    } else if (this.focusIndex === 1) {
277	      // Box Score / Player List focused
278	      if (event.name === 'up') {
279	        if (this.selectedPlayerIdx > -1) {
280	          this.selectedPlayerIdx--;
281	          this.renderBoxScore();
282	          this.scrollBoxScoreIntoView();
283	          this.renderShotChart();
284	        }
285	        return true;
286	      }
287	      if (event.name === 'down') {
288	        if (this.selectedPlayerIdx < this.boxScores.length - 1) {
289	          this.selectedPlayerIdx++;
290	          this.renderBoxScore();
291	          this.scrollBoxScoreIntoView();
292	          this.renderShotChart();
293	        }
294	        return true;
295	      }
296	    } else if (this.focusIndex === 2) {
297	      // Shot chart panel: read-only, no navigation keys
298	      return false;
299	    }
300	    return false;
301	  }
302	
303	  private scrollGameListIntoView() {
304	    const visibleHeight = this.gameListScroll.height || 20;
305	    const currentScroll = this.gameListScroll.scrollTop;
306	    const idx = this.selectedGameIdx;
307	
308	    if (idx < currentScroll) {
309	      this.gameListScroll.scrollTop = idx;
310	    } else if (idx >= currentScroll + visibleHeight - 2) {
311	      this.gameListScroll.scrollTop = Math.max(0, idx - visibleHeight + 3);
312	    }
313	  }
314	
315	  private scrollBoxScoreIntoView() {
316	    const visibleHeight = this.boxScoreScroll.height || 20;
317	    const currentScroll = this.boxScoreScroll.scrollTop;
318	    // Selected player is row index this.selectedPlayerIdx + 3 (+3 accounts for top border, header, separator)
319	    const lineIdx = this.selectedPlayerIdx + 3;
320	
321	    if (lineIdx < currentScroll) {
322	      this.boxScoreScroll.scrollTop = Math.max(0, lineIdx - 2);
323	    } else if (lineIdx >= currentScroll + visibleHeight - 2) {
324	      this.boxScoreScroll.scrollTop = Math.max(0, lineIdx - visibleHeight + 3);
325	    }
326	  }
327	
328	  /**
329	   * Loads rosters, stats, and shots for the selected game.
330	   */
331	  private async loadGameDetails() {
332	    const activeGame = this.games[this.selectedGameIdx];
333	    if (!activeGame) return;
334	
335	    this.boxScoreText.content = ansiToStyledText('Loading box scores...');
336	    this.shotChartText.content = ansiToStyledText('Loading shots...');
337	    this.container.requestRender();
338	
339	    try {
340	      // Fetch box scores with deduplicated team abbreviations
341	      this.boxScores = await loadBoxScoreWithTeamDedup(String(activeGame.game_id));
342	
343	      // Fetch shots
344	      this.shots = await loadGameShots(String(activeGame.game_id));
345	
346	      this.renderBoxScore();
347	      this.renderShotChart();
348	    } catch (e: unknown) {
349	      this.boxScoreText.content = ansiToStyledText(
350	        `Error loading game details:\n${getErrorMessage(e)}`,
351	      );
352	      this.shotChartText.content = ansiToStyledText('');
353	      this.container.requestRender();
354	    }
355	  }
356	
357	  /**
358	   * Renders the game list text buffer with selection indicator.
359	   */
360	  private renderGameList() {
361	    const lines = this.games.map((game, idx) => {
362	      const dateStr = String(game.game_date).substring(5, 10); // MM-DD
363	      const prefix = idx === this.selectedGameIdx ? ' \x1b[1m▶\x1b[0m ' : '   ';
364	      const matchup = `\x1b[1m${game.away_team}\x1b[0m @ \x1b[1m${game.home_team}\x1b[0m`;
365	      const item = `${prefix}[${dateStr}] ${matchup}`;
366	      return item;
367	    });
368	
369	    this.gameListText.content = ansiToStyledText(lines.join('\n'));
370	    this.container.requestRender();
371	  }
372	
373	  /**
374	   * Renders the box score table in the middle panel.
375	   */
376	  private renderBoxScore() {
377	    if (this.boxScores.length === 0) {
378	      this.boxScoreText.content = 'No box score data available.';
379	      this.container.requestRender();
380	      return;
381	    }
382	
383	    // Build the grid headers and rows
384	    const headers = ['Player', 'Team', 'MIN', 'PTS', 'AST', 'REB', 'STL', 'BLK'];
385	    const keys = [
386	      'full_name',
387	      'team_abbrev',
388	      'min',
389	      'points',
390	      'assists',
391	      'reb',
392	      'steals',
393	      'blocks',
394	    ];
395	
396	    // Map rows and insert a selection indicator on player rows
397	    const mappedRows = this.boxScores.map((player, idx) => {
398	      const isSelected = idx === this.selectedPlayerIdx;
399	      return {
400	        ...player,
401	        full_name: isSelected ? `▶ ${player.full_name}` : `  ${player.full_name}`,
402	      };
403	    });
404	
405	    // Prepend a row representing "All Players"
406	    const isAllSelected = this.selectedPlayerIdx === -1;
407	    const allRow = {
408	      full_name: isAllSelected ? '▶ All Players' : '  All Players',
409	      team_abbrev: '---',
410	      min: '---',
411	      points: '---',
412	      assists: '---',
413	      reb: '---',
414	      steals: '---',
415	      blocks: '---',
416	    };
417	
418	    const tableLines = formatTable(headers, [allRow, ...mappedRows], { colKeys: keys });
419	    this.boxScoreText.content = ansiToStyledText(tableLines.join('\n'));
420	    this.container.requestRender();
421	  }
422	
423	  /**
424	   * Renders the shot chart in the right panel.
425	   */
426	  private renderShotChart() {
427	    const activeGame = this.games[this.selectedGameIdx];
428	    if (!activeGame) return;
429	
430	    let filteredShots = this.shots;
431	    let selectedPlayerName = 'All Players';
432	
433	    if (this.selectedPlayerIdx >= 0) {
434	      const selectedPlayer = this.boxScores[this.selectedPlayerIdx];
435	      if (selectedPlayer) {
436	        filteredShots = this.shots.filter(
437	          (s) => String(s.player_id) === String(selectedPlayer.player_id),
438	        );
439	        selectedPlayerName = selectedPlayer.full_name;
440	      }
441	    }
442	
443	    const makes = filteredShots.filter(
444	      (s) => s.shot_result.toLowerCase().includes('made') || s.shot_result === '1',
445	    ).length;
446	    const total = filteredShots.length;
447	    const pct = total > 0 ? ((makes / total) * 100).toFixed(1) : '0.0';
448	
449	    const courtLines = drawHalfCourt(
450	      filteredShots,
451	      this.selectedPlayerIdx >= 0 ? this.boxScores[this.selectedPlayerIdx].player_id : undefined,
452	    );
453	
454	    const zoneSummary = total > 0 ? this.summarizeShotZones(filteredShots) : 'Zones: (no shots)';
455	
456	    // Title / stats overlay
457	    const titleOverlay = `\x1b[1;33m${selectedPlayerName}\x1b[0m\nShots: \x1b[32m${makes}\x1b[0m/\x1b[31m${total - makes}\x1b[0m (${pct}% FG)\n${zoneSummary}`;
458	
459	    this.shotChartText.content = ansiToStyledText(`${titleOverlay}\n\n${courtLines.join('\n')}`);
460	    this.container.requestRender();
461	  }
462	
463	  /**
464	   * Maps shot x/y to court grid cells (same heuristics as drawHalfCourt).
465	   */
466	  private shotGridCoords(shot: { x: number; y: number }): { gridR: number; gridC: number } {
467	    let xHalf = shot.x;
468	    if (xHalf > 50) {
469	      xHalf = 100 - xHalf;
470	    }
471	    const rows = 18;
472	    const cols = 40;
473	    return {
474	      gridR: Math.floor((xHalf / 50) * (rows - 1)),
475	      gridC: Math.floor((shot.y / 100) * (cols - 1)),
476	    };
477	  }
478	
479	  private classifyShotZone(shot: { x: number; y: number }): 'paint' | 'corner3' | 'three' | 'mid' {
480	    const { gridR, gridC } = this.shotGridCoords(shot);
481	
482	    if (gridR >= 1 && gridR <= 7 && gridC > 13 && gridC < 26) {
483	      return 'paint';
484	    }
485	    if (gridR >= 1 && gridR <= 5 && (gridC <= 2 || gridC >= 37)) {
486	      return 'corner3';
487	    }
488	
489	    let xHalf = shot.x;
490	    if (xHalf > 50) {
491	      xHalf = 100 - xHalf;
492	    }
493	    const dy = (gridR - 2) * (47 / 17);
494	    const dx = (gridC - 20) * (50 / 39);
495	    const dist = Math.sqrt(dx * dx + dy * dy);
496	    if (gridR >= 5 && dist >= 22) {
497	      return 'three';
498	    }
499	    return 'mid';
500	  }
501	
502	  private summarizeShotZones(shots: { x: number; y: number }[]): string {
503	    const counts = { paint: 0, corner3: 0, three: 0, mid: 0 };
504	    for (const shot of shots) {
505	      counts[this.classifyShotZone(shot)]++;
506	    }
507	    return `Zones: paint ${counts.paint} | corner 3 ${counts.corner3} | 3PT ${counts.three} | mid ${counts.mid}`;
508	  }
509	}
