9	export class TeamModeController {
10	  teamARoster: TeamRosterRow[] = [];
11	  teamBRoster: TeamRosterRow[] = [];
12	
13	  constructor(private readonly host: TimeMachineHost) {}
14	
15	  showPanels(): void {
16	    this.host.searchPanel.visible = false;
17	    this.host.dossierPanel.visible = false;
18	    this.host.teamSearchPanel.visible = true;
19	    this.host.teamFocusIndex = 0;
