23	    this.host.searchPanel.visible = true;
24	    this.host.dossierPanel.visible = true;
25	    this.host.teamSearchPanel.visible = false;
26	  }
27	
28	  ensureDefaultTeamsLoaded(): void {
29	    if (!this.host.teamAData && this.host.teamAQuery) {
30	      void this.loadTeamData('A');
31	    }
32	    if (!this.host.teamBData && this.host.teamBQuery) {
33	      void this.loadTeamData('B');
34	    }
35	  }
36	
37	  async loadTeamData(type: 'A' | 'B'): Promise<void> {
38	    const inputStr = type === 'A' ? this.host.teamAQuery : this.host.teamBQuery;
39	    const parsed = parseTeamQuery(inputStr);
40	    if (!parsed) {
41	      if (type === 'A') {
42	        this.host.teamAData = null;
43	        this.teamARoster = [];
44	      } else {
45	        this.host.teamBData = null;
46	        this.teamBRoster = [];
47	      }
48	      this.renderTeamComparison();
49	      return;
50	    }
51	
52	    try {
53	      const team = await findTeam(parsed.teamQuery);
54	      if (!team) {
55	        throw new Error(`Team "${parsed.teamQuery}" not found.`);
56	      }
57	
58	      const stats = await loadTeamSeasonStats(team.team_id, parsed.year);
59	      const roster = await loadTeamRoster(team.team_id, parsed.year);
60	
61	      const teamInfo: TeamComparisonData = {
62	        team_id: team.team_id,
63	        team_abbrev: team.team_abbrev,
64	        team_name: team.team_name,
65	        year: parsed.year,
66	        gp: stats?.gp ?? 0,
67	        ppg: stats?.ppg ?? 0,
68	        apg: stats?.apg ?? 0,
69	        rpg: stats?.rpg ?? 0,
70	        spg: stats?.spg ?? 0,
71	        bpg: stats?.bpg ?? 0,
72	      };
73	
74	      if (type === 'A') {
75	        this.host.teamAData = teamInfo;
76	        this.teamARoster = roster;
77	      } else {
78	        this.host.teamBData = teamInfo;
79	        this.teamBRoster = roster;
80	      }
81	
82	      this.renderTeamComparison();
83	    } catch (e: unknown) {
84	      const errorInfo: TeamComparisonData = {
85	        team_name: 'Error',
86	        team_abbrev: 'ERR',
87	        year: parsed.year,
88	        gp: 0,
89	        ppg: 0,
90	        apg: 0,
91	        rpg: 0,
92	        spg: 0,
93	        bpg: 0,
94	        errorMessage: getErrorMessage(e),
95	      };
96	      if (type === 'A') {
97	        this.host.teamAData = errorInfo;
98	        this.teamARoster = [];
99	      } else {
100	        this.host.teamBData = errorInfo;
101	        this.teamBRoster = [];
102	      }
103	      this.renderTeamComparison();
104	    }
105	  }
106	
107	  renderTeamComparison(): void {
108	    if (this.host.mode !== 'team') return;
109	
110	    let content = '============================================================\n';
111	    content += '              HISTORICAL TEAM COMPARISON\n';
112	    content += '============================================================\n';
113	
114	    const formatTeamHeader = (data: TeamComparisonData | null) => {
115	      if (!data) return 'No Team Loaded';
116	      if (data.errorMessage) return `Error: ${data.errorMessage}`;
117	      return `${data.team_abbrev} ${data.year} (${data.team_name})`;
118	    };
119	
120	    const headerA = formatTeamHeader(this.host.teamAData);
121	    const headerB = formatTeamHeader(this.host.teamBData);
122	
123	    const pad = (str: string, len: number) => {
124	      const s = String(str);
125	      return s + ' '.repeat(Math.max(0, len - s.length));
126	    };
127	
128	    content += `${pad('Metric', 18)}│ ${pad(headerA, 28)}│ ${pad(headerB, 28)}\n`;
129	    content += `${'─'.repeat(18)}┼${'─'.repeat(29)}┼${'─'.repeat(29)}\n`;
130	
131	    const getVal = (
132	      data: TeamComparisonData | null,
133	      key: keyof TeamComparisonData,
134	      isFloat = true,
135	    ) => {
136	      if (!data || data.errorMessage) return '---';
137	      const val = data[key];
138	      if (val === undefined || val === null) return '---';
139	      return isFloat ? Number(val).toFixed(1) : String(val);
140	    };
141	
142	    content += `${pad('Games Played', 18)}│ ${pad(getVal(this.host.teamAData, 'gp', false), 28)}│ ${pad(getVal(this.host.teamBData, 'gp', false), 28)}\n`;
143	    content += `${pad('Points / Game', 18)}│ ${pad(getVal(this.host.teamAData, 'ppg'), 28)}│ ${pad(getVal(this.host.teamBData, 'ppg'), 28)}\n`;
144	    content += `${pad('Assists / Game', 18)}│ ${pad(getVal(this.host.teamAData, 'apg'), 28)}│ ${pad(getVal(this.host.teamBData, 'apg'), 28)}\n`;
145	    content += `${pad('Rebounds / Game', 18)}│ ${pad(getVal(this.host.teamAData, 'rpg'), 28)}│ ${pad(getVal(this.host.teamBData, 'rpg'), 28)}\n`;
146	    content += `${pad('Steals / Game', 18)}│ ${pad(getVal(this.host.teamAData, 'spg'), 28)}│ ${pad(getVal(this.host.teamBData, 'spg'), 28)}\n`;
147	    content += `${pad('Blocks / Game', 18)}│ ${pad(getVal(this.host.teamAData, 'bpg'), 28)}│ ${pad(getVal(this.host.teamBData, 'bpg'), 28)}\n`;
148	
149	    content += '\n============================================================\n';
150	    content += '              ROSTER SIDE-BY-SIDE (PPG / APG / RPG)\n';
151	    content += '============================================================\n';
152	
153	    const nameA =
154	      this.host.teamAData && !this.host.teamAData.errorMessage
155	        ? `${this.host.teamAData.team_abbrev} ${this.host.teamAData.year}`
156	        : 'Team A';
157	    const nameB =
158	      this.host.teamBData && !this.host.teamBData.errorMessage
159	        ? `${this.host.teamBData.team_abbrev} ${this.host.teamBData.year}`
160	        : 'Team B';
161	
162	    content += `${pad(`${nameA} Roster`, 30)}│ ${pad(`${nameB} Roster`, 30)}\n`;
163	    content += `${'─'.repeat(30)}┼${'─'.repeat(31)}\n`;
164	
165	    const maxRosterLen = Math.max(this.teamARoster.length, this.teamBRoster.length);
166	    if (maxRosterLen === 0) {
167	      content += ' No roster data available.    │  No roster data available.\n';
168	    } else {
169	      const truncate = (str: string, len: number) => {
170	        if (str.length <= len) return str;
171	        return `${str.slice(0, len - 3)}...`;
172	      };
173	
174	      for (let i = 0; i < maxRosterLen; i++) {
175	        const pA = this.teamARoster[i];
176	        const pB = this.teamBRoster[i];
177	
178	        const nameA_trunc = pA ? truncate(pA.full_name, 18) : '';
179	        const nameB_trunc = pB ? truncate(pB.full_name, 18) : '';
180	        const statsA = pA ? `(${Number(pA.ppg).toFixed(1)}/${Number(pA.apg).toFixed(1)})` : '';
181	        const statsB = pB ? `(${Number(pB.ppg).toFixed(1)}/${Number(pB.apg).toFixed(1)})` : '';
182	
183	        const strA = pA ? `${nameA_trunc} ${statsA}` : '';
184	        const strB = pB ? `${nameB_trunc} ${statsB}` : '';
185	
186	        content += `${pad(strA, 30)}│ ${pad(strB, 31)}\n`;
187	      }
188	    }
189	
190	    this.host.statsText.content = ansiToStyledText(content);
191	    this.host.requestRender();
192	  }
193	
194	  renderTeamInstructions(): void {
195	    let content =
196	      '\n\x1b[90mInstructions:\x1b[0m\nType Team name/abbreviation with a 4-digit year. Press [Enter] to fetch stats. Use [Tab] to move, [C] to toggle.\n';
197	
198	    content += '\n\x1b[1;33mSub-pages (Press keys anywhere to load):\x1b[0m\n';
