205	    content += ` ${subpageIndicator('team_b_profile', 'G', 'Team B Page')} · ${subpageIndicator('leaders_index', 'L', 'Leaders')} · ${subpageIndicator('leagues_index', 'E', 'Leagues')}\n`;
206	    content += ` ${subpageIndicator('contracts', 'T', 'Contracts')} · ${subpageIndicator('season_summary', 'U', 'Season')} · ${subpageIndicator('team_season', 'S', 'ATL 2000')}\n`;
207	    content += ` ${subpageIndicator('playoffs', 'Y', 'Playoffs')} · ${subpageIndicator('awards', 'W', 'Awards')} · ${subpageIndicator('team_adv_gamelog', 'A', 'CHI Adv Log')}\n`;
208	    content += ` ${subpageIndicator('game_boxscore', 'V', 'Boxscore')} · ${subpageIndicator('game_shot_chart', 'X', 'Shot Chart')} · ${subpageIndicator('game_pbp', 'Z', 'Play-by-Play')}\n`;
