221	      if (event.name === 'return' || event.name === 'enter') {
222	        void this.loadTeamData('B');
223	        return true;
224	      }
225	    } else if (this.host.teamFocusIndex === 2) {
226	      return this.host.statsScroll.handleKeyPress(event);
227	    }
